-- NUR FÜR LOKALE TESTS – NIEMALS IN SUPABASE AUSFÜHREN. Prüft Migration 012 (Belohnungen ohne 15-Minuten-Sperre).
\set ON_ERROR_STOP on
create function pg_temp.ok(b boolean, t text) returns void language plpgsql as $$ begin if coalesce(b, false) then raise notice '✓ %', t; else raise exception '✗ %', t; end if; end $$;
select pg_temp.ok((select bool_and(pg_get_functiondef(p.oid) !~* '15 minutes') and count(*) = 2 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('rpg_claim_ending', 'rpg_award_xp')), 'Beide Funktionen: keine 15-Minuten-Bedingung mehr');
select pg_temp.ok((select bool_and(pg_get_functiondef(p.oid) ~ 'current_version < 8' and pg_get_functiondef(p.oid) ~ 'completed_at is null' and pg_get_functiondef(p.oid) ~ 'abgeschlossen') from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('rpg_claim_ending', 'rpg_award_xp')), 'Die übrigen Bedingungen stehen noch: abgeschlossen, mindestens 8 Stände');
select pg_temp.ok((select bool_and(has_function_privilege('authenticated', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and p.prosecdef) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('rpg_claim_ending', 'rpg_award_xp')), 'Rechte unverändert: nur angemeldete Nutzer, weiterhin security definer');
